particle_effect.pre_effect_expression:
variable.posx = t.starx;
variable.posy = t.stary;
variable.posz = t.starz;
variable.rotx = t.rx;
variable.roty = t.ry;
variable.rotz = t.rz;

calc.expression:
v.index = v.index + 1;
v.angle = v.index * 360 / v.count;
t.starx = 0;
t.starz = 0;
t.starx = math.cos(v.angle) * v.radius;
t.starz = math.sin(v.angle) * v.radius;
t.stary = -120;

v.normalized = math.sqrt(t.starx * t.starx + t.starz * t.starz + t.stary * t.stary);
t.rx = 0;
t.ry = 0;
t.rz = 0;
t.rx = t.starx / v.normalized;
t.ry = t.stary / v.normalized;
t.rz = t.starz / v.normalized;
